'use client';

import { usePreviewToast } from './PreviewToast';

import { useRef, useState } from 'react';
import { Swiper, SwiperSlide } from 'swiper/react';
import { A11y, EffectCards } from 'swiper/modules';
import type { Swiper as SwiperInstance } from 'swiper';
import { useReducedMotion } from 'framer-motion';
import Image from 'next/image';
import { HugeiconsIcon } from '@hugeicons/react';
import { Airplane01Icon } from '@hugeicons/core-free-icons';
import cappadocia from './assets/abubakarhasan-components-cappadocia.webp.asset';
import pyramid from './assets/abubakarhasan-components-pyramid.webp.asset';
import wall from './assets/abubakarhasan-components-great-wall.webp.asset';
import santorini from './assets/abubakarhasan-components-santorini.webp.asset';
import kyoto from './assets/abubakarhasan-components-kyoto.webp.asset';
import bali from './assets/abubakarhasan-components-bali.webp.asset';
import petra from './assets/abubakarhasan-components-petra.webp.asset';
import dolomites from './assets/abubakarhasan-components-dolomites.webp.asset';

const destinations = [
  { name: 'Cappadocia', location: 'Göreme, Turkey', image: cappadocia, alt: 'Hot air balloons above Cappadocia at sunrise' },
  { name: 'The Great Wall', location: 'Beijing, China', image: wall, alt: 'The Great Wall winding across green mountain ridges' },
  { name: 'The Great Pyramid', location: 'Giza, Egypt', image: pyramid, alt: 'Golden limestone pyramid under a turquoise sky' },
  { name: 'Santorini', location: 'Oia, Greece', image: santorini, alt: 'Blue-domed church and whitewashed buildings above the Aegean Sea' },
  { name: 'Kyoto', location: 'Kyoto, Japan', image: kyoto, alt: 'Vermilion torii gates along a forest path at Fushimi Inari' },
  { name: 'Bali', location: 'Ubud, Indonesia', image: bali, alt: 'Emerald rice terraces and palms in soft morning light' },
  { name: 'Petra', location: 'Petra, Jordan', image: petra, alt: 'Rose sandstone Treasury framed by the narrow Siq canyon' },
  { name: 'The Dolomites', location: 'Braies, Italy', image: dolomites, alt: 'Wooden boats on a turquoise alpine lake beneath the Dolomites' },
];

export default function DestinationStack() {
  const notify = usePreviewToast();
  const [active, setActive] = useState(0);
  const [selected, setSelected] = useState(false);
  const swiperRef = useRef<SwiperInstance | null>(null);
  const reducedMotion = useReducedMotion();

  return <div className="sc-destination-demo sc-new-demo">
    <Swiper
      modules={[EffectCards, A11y]}
      effect="cards"
      grabCursor
      rewind
      speed={reducedMotion ? 0 : 400}
      cardsEffect={{ slideShadows: false, perSlideOffset: 8, perSlideRotate: 3, rotate: !reducedMotion }}
      className="sc-destination-deck"
      tabIndex={0}
      role="region"
      aria-label="Destinations. Swipe or use the left and right arrow keys to browse."
      onSwiper={swiper => { swiperRef.current = swiper; }}
      onSlideChange={swiper => { setActive(swiper.activeIndex); setSelected(false); }}
      onKeyDown={event => {
        if (event.key === 'ArrowRight') { event.preventDefault(); swiperRef.current?.slideNext(); }
        if (event.key === 'ArrowLeft') { event.preventDefault(); swiperRef.current?.slidePrev(); }
      }}
    >
      {destinations.map((place, index) => <SwiperSlide key={place.name} className="sc-destination-slide">
        <article className="sc-destination-card" inert={index !== active} aria-hidden={index !== active}>
          <div className="sc-destination-image"><Image src={place.image} alt={place.alt} fill sizes="(max-width: 640px) 65vw, 360px" /><HugeiconsIcon icon={Airplane01Icon} className="sc-destination-plane" aria-hidden="true" /></div>
          <div className="sc-destination-caption"><h3>{place.name}</h3><p>{place.location}</p></div>
          <button type="button" className="sc-destination-book" aria-pressed={selected && index === active} onClick={() => { setSelected(!selected); notify(selected ? 'Trip selection cleared.' : 'Trip selected — demo only, no booking made.'); }}>{selected && index === active ? 'Trip selected' : 'Book Now'}</button>
        </article>
      </SwiperSlide>)}
    </Swiper>
  </div>;
}

'use client';

import { createContext, useCallback, useContext, useEffect, useRef, useState, type ReactNode } from 'react';
import { HugeiconsIcon } from '@hugeicons/react';
import { CheckmarkCircle02Icon } from '@hugeicons/core-free-icons';

const ToastContext = createContext<((message: string) => void) | null>(null);

export function usePreviewToast() {
  const notify = useContext(ToastContext);
  if (!notify) throw new Error('Component previews must be rendered inside PreviewToast.');
  return notify;
}

/** Shared by every preview. Use the hook for actions, or data-preview-toast on simple demo buttons. */
export default function PreviewToast({ children }: { children: ReactNode }) {
  const [toast, setToast] = useState<{ id: number; message: string } | null>(null);
  const sequence = useRef(0);
  const notify = useCallback((message: string) => {
    if (message.trim()) setToast({ id: ++sequence.current, message });
  }, []);

  useEffect(() => {
    if (!toast) return;
    const timer = setTimeout(() => setToast(current => current?.id === toast.id ? null : current), 2800);
    return () => clearTimeout(timer);
  }, [toast]);

  return <ToastContext.Provider value={notify}>
    <div className="sc-toast-boundary" onClick={event => {
      if (!(event.target instanceof Element)) return;
      const trigger = event.target.closest<HTMLElement>('[data-preview-toast]');
      if (trigger && event.currentTarget.contains(trigger)) {
        const message = trigger.dataset.previewToast;
        if (message) notify(message);
      }
    }}>
      {children}
      <div className="sc-toast-layer" role="status" aria-live="polite" aria-atomic="true">
        {toast && <div key={toast.id} className="sc-preview-toast"><HugeiconsIcon icon={CheckmarkCircle02Icon} aria-hidden="true" /><span>{toast.message}</span></div>}
      </div>
    </div>
  </ToastContext.Provider>;
}

export const component = {
  "slug": "destination-stack",
  "name": "Destination stack",
  "category": "Travel · Card carousel",
  "description": "Eight dream destinations, layered like postcards. Swipe from Cappadocia, the Great Wall, and Giza to Santorini, Kyoto, Bali, Petra, and the Dolomites.",
  "designStory": "The slightly rotated side cards suggest there is more to discover without filling the page with controls. Bringing one postcard to the front keeps the photograph, destination, and booking action in a clear order.",
  "interactionHint": "Swipe or drag the stack to explore. You can also focus the stack and use the left and right arrow keys. Book Now selects a demo trip without making a reservation.",
  "stage": "destinations"
};

import Component from './Preview';
import PreviewToast from './PreviewToast';
import '@fontsource-variable/plus-jakarta-sans';
import './styles.css';

/** Copy this entire folder and import this entry point. */
export default function DestinationStack() {
  return <div className="sc-package-destination-stack"><PreviewToast><Component /></PreviewToast></div>;
}

@import "swiper/css" layer(base);
@import "swiper/css/effect-cards" layer(base);
@import "swiper/css/a11y" layer(base);
@reference "tailwindcss";

/* This folder owns its presentation and container sizing. */
@layer components {
  .sc-package-destination-stack { width:100%; min-width:0; container-type:inline-size; font-family:var(--font-plus-jakarta-sans, "Plus Jakarta Sans Variable"), sans-serif; color:#0F0F0F; }
}


@layer components {
  :where(.sc-package-destination-stack) .sc-new-demo { @apply relative w-full; font-size:3cqw; letter-spacing:-.04em; }
  :where(.sc-package-destination-stack) .sc-new-demo button { @apply cursor-pointer; }
  :where(.sc-package-destination-stack) .sc-new-demo button:focus-visible { @apply outline-2 outline-offset-4 outline-[#6C47FF]; }
  :where(.sc-package-destination-stack) .sc-destination-demo { padding:8cqw 0; }
  :where(.sc-package-destination-stack) .sc-destination-deck { @apply relative mx-auto overflow-visible; width:62%; }
  :where(.sc-package-destination-stack) .sc-destination-deck:focus-visible { @apply outline-2 outline-offset-8 outline-[#6C47FF]; }
  :where(.sc-package-destination-stack) .sc-destination-slide { @apply h-auto; border-radius:5cqw; }
  :where(.sc-package-destination-stack) .sc-destination-card { @apply relative w-full bg-white; padding:1.8cqw; border-radius:5cqw; box-shadow:0 2cqw 5cqw #00000010; }
  :where(.sc-package-destination-stack) .sc-destination-image { @apply relative overflow-hidden; aspect-ratio:.85; border-radius:3.5cqw; }
  :where(.sc-package-destination-stack) .sc-destination-image img { @apply object-cover; }
  :where(.sc-package-destination-stack) .sc-destination-plane { @apply absolute rounded-full bg-[#202421] text-white; width:8cqw; height:8cqw; padding:1.5cqw; top:1.2cqw; right:1.2cqw; border:.5cqw solid white; }
  :where(.sc-package-destination-stack) .sc-destination-caption { @apply flex items-baseline justify-between; gap:1cqw; padding:3cqw .5cqw; }
  :where(.sc-package-destination-stack) .sc-destination-caption h3 { @apply font-medium; font-size:3.6cqw; line-height:1.1; }
  :where(.sc-package-destination-stack) .sc-destination-caption p { @apply shrink-0 text-[#888]; font-size:1.8cqw; }
  :where(.sc-package-destination-stack) .sc-destination-book { @apply w-full bg-[#252525] text-white; border-radius:3cqw; padding:2cqw; font-size:2.3cqw; }
  :where(.sc-package-destination-stack) .sc-screen-reader { @apply sr-only; }
}
@layer components {
  :where(.sc-package-destination-stack) .sc-toast-boundary { @apply relative w-full; isolation:isolate; }
  :where(.sc-package-destination-stack) .sc-toast-layer { @apply pointer-events-none absolute inset-0 z-50 grid place-items-center; padding:4%; }
  :where(.sc-package-destination-stack) .sc-preview-toast { @apply flex items-center justify-center gap-2 rounded-2xl border border-white/15 bg-[#17131f]/90 px-4 py-3 text-center font-medium text-white shadow-sm backdrop-blur-md; max-width:min(100%,340px); font-size:clamp(10px,2.7cqw,14px); line-height:1.5; overflow-wrap:anywhere; animation:scToastLifecycle 2800ms cubic-bezier(.22,1,.36,1) both; }
  :where(.sc-package-destination-stack) .sc-preview-toast svg { @apply size-4 shrink-0 text-[#c4b5fd]; }
  @media (prefers-reduced-motion:reduce) { :where(.sc-package-destination-stack) .sc-preview-toast { animation-name:scToastFade; } }
}
@keyframes scToastLifecycle {
  0% { opacity:0; transform:translateY(6px) scale(.98); }
  12%,72% { opacity:1; transform:translateY(0) scale(1); }
  100% { opacity:0; transform:translateY(-3px) scale(1); }
}
@keyframes scToastFade {
  0% { opacity:0; }
  8%,78% { opacity:1; }
  100% { opacity:0; }
}
